const query = $fromAI('query', '要搜尋的問題');
const embedResp = await $http.request({
  method: 'POST',
  url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-embedding-001:embedContent?key=YOUR_GEMINI_API_KEY',
  headers: {'Content-Type': 'application/json'},
  body: JSON.stringify({ content: { parts: [{ text: query }] }, taskType: 'RETRIEVAL_QUERY', outputDimensionality: 768 })
});
const vector = JSON.parse(embedResp.body).embedding.values;
const searchResp = await $http.request({
  method: 'POST',
  url: 'http://host.containers.internal:6333/collections/sop_knowledge/points/search',
  headers: {'Content-Type': 'application/json'},
  body: JSON.stringify({ vector, limit: 5, with_payload: true })
});
const hits = JSON.parse(searchResp.body).result || [];
if (!hits.length) return '（知識庫無相關資料）';
return hits.map((h,i) => '[' + (i+1) + '] ' + h.payload.source + ' > ' + h.payload.section + '
' + h.payload.text).join('

---

');
